import math


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1
            tokens.append(("NUM", int(expr[start:i])))
        elif ch in "+-*/%^!()":
            tokens.append(("OP", ch))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {ch!r}")

    if not tokens:
        raise ValueError("Empty expression")

    tokens.append(("EOF", None))
    pos = 0

    def peek():
        return tokens[pos]

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_add_sub() -> int:
        val = parse_mul_div()
        while True:
            tok_type, tok_val = peek()
            if tok_type == "OP" and tok_val in ("+", "-"):
                advance()
                rhs = parse_mul_div()
                if tok_val == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_mul_div() -> int:
        val = parse_unary()
        while True:
            tok_type, tok_val = peek()
            if tok_type == "OP" and tok_val in ("*", "/", "%", "("):
                if tok_val != "(":
                    advance()
                rhs = parse_unary()
                if tok_val in ("*", "("):
                    val *= rhs
                elif tok_val == "/":
                    if rhs == 0:
                        raise ValueError("Division by zero")
                    q = abs(val) // abs(rhs)
                    val = -q if (val < 0) != (rhs < 0) else q
                else:
                    if rhs == 0:
                        raise ValueError("Remainder by zero")
                    q = abs(val) // abs(rhs)
                    if (val < 0) != (rhs < 0):
                        q = -q
                    val = val - q * rhs
            else:
                break
        return val

    def parse_unary() -> int:
        neg = False
        while peek() == ("OP", "-"):
            advance()
            neg = not neg
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        stack = []
        while True:
            base = parse_postfix()
            if peek() == ("OP", "^"):
                advance()
                neg = False
                while peek() == ("OP", "-"):
                    advance()
                    neg = not neg
                stack.append((base, neg))
            else:
                val = base
                break
        while stack:
            b, neg = stack.pop()
            exp = -val if neg else val
            if exp < 0:
                raise ValueError("Negative exponent")
            val = pow(b, exp)
        return val

    def parse_postfix() -> int:
        val = parse_atom()
        while peek() == ("OP", "!"):
            advance()
            if val < 0:
                raise ValueError("Factorial of negative number")
            val = math.factorial(val)
        return val

    def parse_atom() -> int:
        tok_type, tok_val = peek()
        if tok_type == "NUM":
            advance()
            return tok_val
        if tok_type == "OP" and tok_val == "(":
            advance()
            val = parse_add_sub()
            if peek() != ("OP", ")"):
                raise ValueError("Mismatched parentheses")
            advance()
            return val
        raise ValueError(f"Unexpected token: {tok_type}")

    result = parse_add_sub()
    if peek()[0] != "EOF":
        raise ValueError("Malformed expression")
    return result
